// ✅ Tách bạch Urgent State vs Non-Urgent Transition với useTransition
import { useState, useTransition } from 'react';

function SearchDemo() {
  const [query, setQuery] = useState('');
  const [filteredList, setFilteredList] = useState(allData);
  const [isPending, startTransition] = useTransition();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value); // 1. Cập nhật input tức thì (60 FPS)

    startTransition(() => {
      // 2. Chuyển tác vụ tính toán lọc danh sách vào hàng đợi nền
      setFilteredList(allData.filter(item => item.includes(e.target.value)));
    });
  };

  return (
    <div>
      <input value={query} onChange={handleChange} placeholder="Tìm kiếm..." />
      {isPending && <span className="text-xs text-muted-foreground">Đang lọc kết quả...</span>}
      <HeavyList items={filteredList} opacity={isPending ? 0.6 : 1} />
    </div>
  );
}

