// ✅ Compound Components: Linh hoạt tối đa, tự do cấu trúc JSX
import React, { createContext, useContext, useState } from 'react';

const TabsContext = createContext<{ active: string; setActive: (id: string) => void } | null>(null);

export function Tabs({ defaultValue, children }: { defaultValue: string; children: React.ReactNode }) {
  const [active, setActive] = useState(defaultValue);
  return <TabsContext.Provider value={{ active, setActive }}><div className="tabs-root">{children}</div></TabsContext.Provider>;
}

Tabs.Trigger = function TabTrigger({ value, children }: { value: string; children: React.ReactNode }) {
  const ctx = useContext(TabsContext)!;
  return (
    <button
      className={ctx.active === value ? 'font-bold border-b-2 text-primary' : 'text-muted-foreground'}
      onClick={() => ctx.setActive(value)}
    >
      {children}
    </button>
  );
};

Tabs.Content = function TabContent({ value, children }: { value: string; children: React.ReactNode }) {
  const ctx = useContext(TabsContext)!;
  if (ctx.active !== value) return null;
  return <div className="tab-panel p-4">{children}</div>;
};

